import {projects as demos} from './catalog.js';
import {normalize,cleanProject,backup,mergeBackup,icsEvent} from './model.js';
const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let raw;try{raw=JSON.parse(localStorage.getItem('airdrop-museum-v1'))||{}}catch{raw={}}let state;try{state=normalize(raw,demos)}catch{state=normalize({},demos)}
const nav=[['home','⌂','Dashboard'],['explore','⌕','Discover'],['workspace','☑','Workspace'],['calendar','▦','Calendar'],['archive','◇','Archive'],['profile','♙','Profile']];
const labels={watching:'Watchlist',active:'In progress',completed:'Completed',archived:'Archived'};
let page='home',query='',category='All',chain='All',sort='featured',mode='all',month=new Date(new Date().getFullYear(),new Date().getMonth(),1),openId=null;
const all=()=>[...demos,...state.custom],project=id=>all().find(p=>p.id===id),rec=p=>state.records[p.id],done=p=>p.tasks.filter((_,i)=>state.done[p.id+':'+i]).length,total=()=>all().reduce((n,p)=>n+done(p),0),today=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`},money=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:2}).format(n);
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3000)}
function persist(text){if(text)state.history.unshift({at:new Date().toISOString(),text});state.history=state.history.slice(0,100);try{localStorage.setItem('airdrop-museum-v1',JSON.stringify(state))}catch{toast('Penyimpanan tidak tersedia. Ekspor backup sebelum menutup aplikasi.')}}
function navigate(id){page=nav.some(n=>n[0]===id)?id:'home';query='';category=chain='All';mode='all';location.hash=page;render();window.scrollTo(0,0)}
function intro(title,desc,action=''){return `<div class="intro"><div><span class="eyeline">AIRDROP MUSEUM / RESEARCH DESK</span><h1>${title}</h1><p>${desc}</p></div>${action}</div>`}
const empty=(text,button='')=>`<div class="empty">${text}${button}</div>`;
function stats(){const tracked=all().filter(p=>state.saved.includes(p.id)&&rec(p).status!=='archived');return `<div class="stats">${[['◇',tracked.length,'Tracked projects'],['☑',tracked.filter(p=>rec(p).status==='active').length,'In progress'],['✓',total(),'Research tasks done'],['▦',tracked.filter(p=>rec(p).due&&rec(p).due>=today()).length,'Upcoming deadlines']].map(([i,n,l])=>`<div class="stat"><span class="stat-icon">${i}</span><div><b>${n}</b><small>${l}</small></div></div>`).join('')}</div>`}
function row(p){const r=rec(p);return `<button class="project-row" data-open="${esc(p.id)}"><span class="row-symbol">${p.symbol}</span><span><b>${esc(p.name)}</b><small>${esc(p.chain)} · ${p.custom?'Personal project':'Demo'} · ${labels[r.status]}</small></span><span class="row-meta">${done(p)}/${p.tasks.length}<small>${r.due||'No deadline'}</small></span><span>↗</span></button>`}
function activity(){return state.history.length?`<ol class="activity">${state.history.slice(0,8).map(h=>`<li><span>${esc(h.text)}</span><time>${esc(new Date(h.at).toLocaleString('id-ID'))}</time></li>`).join('')}</ol>`:empty('Aktivitas riset Anda akan muncul di sini.')}
function dashboard(){const active=all().filter(p=>state.saved.includes(p.id)&&rec(p).status==='active'),due=all().filter(p=>state.saved.includes(p.id)&&rec(p).due&&!['completed','archived'].includes(rec(p).status)).sort((a,b)=>rec(a).due.localeCompare(rec(b).due));return intro('Your research, in focus.','Ringkasan pekerjaan, tenggat, dan aktivitas—tanpa katalog berulang.',`<button class="primary" data-nav="explore">Find a project ↗</button>`)+stats()+`<div class="split"><section class="panel"><div class="section-title"><h3>Continue your work</h3><button class="text-btn" data-nav="workspace">Open workspace ↗</button></div>${active.length?active.slice(0,4).map(row).join(''):empty('Belum ada proyek aktif. Tambahkan proyek dari Discover, lalu ubah statusnya ke In progress.')}</section><section class="panel"><div class="section-title"><h3>Deadlines to watch</h3><button class="text-btn" data-nav="calendar">Calendar ↗</button></div>${due.length?due.slice(0,4).map(row).join(''):empty('Belum ada tenggat. Atur tanggal target di detail proyek.')}</section></div><section class="panel"><h3>Recent activity</h3>${activity()}</section><div class="notice">Research workspace: penyelesaian tugas dicatat sendiri. Data demo bukan kampanye aktif atau jaminan eligibility.</div>`}
function card(p){const saved=state.saved.includes(p.id);return `<article class="card"><div class="card-art"><span class="tag">${p.custom?'Personal project':'Demo project'}</span><button class="save ${saved?'saved':''}" data-save="${esc(p.id)}" aria-label="${saved?'Untrack':'Track'} ${esc(p.name)}" aria-pressed="${saved}">${saved?'◆':'◇'}</button><span class="project-symbol">${p.symbol}</span></div><div class="card-body"><div class="card-heading"><h3>${esc(p.name)}</h3></div><p>${esc(p.desc)}</p><div class="tags"><span class="tag-inline">${esc(p.category)}</span><span class="tag-inline">${esc(p.chain)}</span></div><div class="card-bottom"><span>${p.custom?'Source: owner supplied':'Fictional sample'}</span><button class="text-btn" data-open="${esc(p.id)}">Research ↗</button></div></div></article>`}
function discover(){return intro('Discover with intention.','Cari proyek, periksa sumber, lalu pilih yang layak masuk workspace.',`<button class="primary" id="add-project">+ Add project</button>`)+`<div class="toolbar"><label class="search"><span>⌕</span><input id="search" type="search" aria-label="Cari proyek" placeholder="Search name, chain, category..."></label><select id="chain" aria-label="Filter chain"><option value="All">All chains</option>${[...new Set(all().map(p=>p.chain))].map(c=>`<option>${esc(c)}</option>`).join('')}</select><select id="mode" aria-label="Sumber proyek"><option value="all">All sources</option><option value="personal">Personal only</option><option value="demo">Demo only</option></select><select id="sort" aria-label="Urutan"><option value="featured">Curated order</option><option value="name">Name A–Z</option></select></div><div class="filters">${['All','Testnet','DeFi','Gaming','AI','Infra','NFT'].map(c=>`<button class="chip ${c===category?'active':''}" data-category="${c}" aria-pressed="${c===category}">${c}</button>`).join('')}</div><div class="section-title"><h2>Project directory</h2><small id="count"></small></div><div class="grid" id="project-grid"></div>`}
function updateGrid(){const list=all().filter(p=>(category==='All'||p.category===category)&&(chain==='All'||p.chain===chain)&&(mode==='all'||(mode==='personal'?p.custom:!p.custom))&&[p.name,p.chain,p.category].join(' ').toLowerCase().includes(query.toLowerCase()));if(sort==='name')list.sort((a,b)=>a.name.localeCompare(b.name));$('#project-grid').innerHTML=list.length?list.map(card).join(''):empty('Tidak ada proyek yang cocok. Coba filter lain.');$('#count').textContent=list.length+' projects';document.querySelectorAll('[data-category]').forEach(el=>{el.classList.toggle('active',el.dataset.category===category);el.setAttribute('aria-pressed',el.dataset.category===category)})}
function workspace(){const tracked=all().filter(p=>state.saved.includes(p.id)&&rec(p).status!=='archived');return intro('A workspace that moves with you.','Kelola prioritas, checklist, catatan, biaya, dan hasil aktual per proyek.')+`<div class="kanban">${['watching','active','completed'].map(status=>`<section class="lane"><div class="section-title"><h3>${labels[status]}</h3><small>${tracked.filter(p=>rec(p).status===status).length}</small></div>${tracked.filter(p=>rec(p).status===status).map(p=>`<article class="work-card"><button class="work-title" data-open="${esc(p.id)}">${p.symbol} ${esc(p.name)} ↗</button><span class="tag-inline">${rec(p).priority.toUpperCase()}</span><p>${done(p)}/${p.tasks.length} tasks · ${rec(p).due||'No deadline'}</p><div class="progress"><span style="width:${done(p)/p.tasks.length*100}%"></span></div><p class="note-preview">${esc(rec(p).notes||'Belum ada catatan riset.')}</p><button class="text-btn" data-open="${esc(p.id)}">Manage project →</button></article>`).join('')||empty('Belum ada proyek di tahap ini.')}</section>`).join('')}</div>`}
function calendar(){const y=month.getFullYear(),m=month.getMonth(),start=(new Date(y,m,1).getDay()+6)%7,days=new Date(y,m+1,0).getDate(),due=all().filter(p=>state.saved.includes(p.id)&&rec(p).due&&rec(p).status!=='archived');return intro('Never lose sight of a deadline.','Tanggal di sini adalah target pribadi yang Anda tetapkan, bukan tenggat resmi kampanye.',`<button class="secondary" id="export-calendar">Export calendar ↓</button>`)+`<section class="panel"><div class="section-title"><button class="secondary" data-month="-1" aria-label="Bulan sebelumnya">←</button><h2>${month.toLocaleDateString('id-ID',{month:'long',year:'numeric'})}</h2><button class="secondary" data-month="1" aria-label="Bulan berikutnya">→</button></div><div class="calendar-grid">${['Sen','Sel','Rab','Kam','Jum','Sab','Min'].map(d=>`<b class="weekday">${d}</b>`).join('')}${Array.from({length:start},()=>'<div class="day blank"></div>').join('')}${Array.from({length:days},(_,i)=>{const date=`${y}-${String(m+1).padStart(2,'0')}-${String(i+1).padStart(2,'0')}`;return `<div class="day ${date===today()?'today':''}"><span>${i+1}</span>${due.filter(p=>rec(p).due===date).map(p=>`<button data-open="${esc(p.id)}">${esc(p.name)}</button>`).join('')}</div>`}).join('')}</div></section><section class="panel"><h3>All scheduled projects</h3>${due.length?due.sort((a,b)=>rec(a).due.localeCompare(rec(b).due)).map(row).join(''):empty('Atur deadline di detail proyek untuk mulai menjadwalkan riset.')}</section>`}
function archive(){const list=all().filter(p=>rec(p).status==='archived'),recorded=all().filter(p=>rec(p).cost||rec(p).reward),cost=recorded.reduce((n,p)=>n+rec(p).cost,0),reward=recorded.reduce((n,p)=>n+rec(p).reward,0);return intro('Keep the lessons. Track the outcomes.','Arsip proyek dan pencatatan biaya/hasil manual. Tidak ada estimasi penghasilan.')+`<div class="stats">${[[list.length,'Archived projects'],[money(cost),'Recorded costs'],[money(reward),'Recorded rewards'],[money(reward-cost),'Net recorded']].map(([n,l])=>`<div class="stat"><div><b>${n}</b><small>${l}</small></div></div>`).join('')}</div><section class="panel"><h3>Archived research</h3>${list.length?list.map(row).join(''):empty('Arsip masih kosong. Arsipkan proyek melalui pengaturan status di detail.')}</section><section class="panel"><h3>Outcome ledger · USD</h3><p>Catatan manual pribadi, bukan saldo wallet atau bukti transaksi.</p>${recorded.length?`<div class="table-wrap"><table><thead><tr><th>Project</th><th>Cost</th><th>Reward</th><th>Net</th></tr></thead><tbody>${recorded.map(p=>`<tr><td><button class="text-btn" data-open="${esc(p.id)}">${esc(p.name)}</button></td><td>${money(rec(p).cost)}</td><td>${money(rec(p).reward)}</td><td>${money(rec(p).reward-rec(p).cost)}</td></tr>`).join('')}</tbody></table></div>`:empty('Belum ada biaya atau hasil dicatat.')}</section>`}
function profile(){return intro('Your identity. Your preferences.','Kelola profil lokal, backup lengkap, dan status integrasi.')+`<div class="split"><section class="panel"><h3>Explorer profile</h3><form id="profile-form"><label>Display name<input name="name" value="${esc(state.name)}" maxlength="60" required></label><button class="primary">Save profile</button></form><p>Profil lokal browser · ${total()} tugas selesai</p><div class="badge-grid">${[['◇','Researcher',state.saved.length>0],['✓','First steps',total()>0],['✦','Task curator',total()>=12]].map(([s,n,yes])=>`<div class="badge"><strong style="opacity:${yes?1:.3}">${s}</strong>${n}<br>${yes?'Unlocked':'Locked'}</div>`).join('')}</div></section><section class="panel"><h3>Integration status</h3><div class="status-row"><b>Cloudflare C0</b><span>Deployed</span></div><div class="status-row"><b>Telegram display SDK</b><span>${window.Telegram?.WebApp?.initData?'Inside Telegram':'Browser mode'}</span></div><div class="status-row"><b>Verified login / sync</b><span>Not configured</span></div><div class="status-row"><b>Wallet / claims</b><span>Not connected</span></div><p>Data tetap di browser ini. Tidak ada transaksi atau task verification otomatis.</p></section></div><section class="panel"><h3>Data portability</h3><p>Ekspor proyek pribadi, checklist, catatan, jadwal, dan pencatatan hasil. Impor menggabungkan progres; pengaturan proyek yang sudah ada tetap dipertahankan.</p><div class="data-actions"><button class="secondary" id="export">Export full backup ↓</button><label class="secondary import-label">Import backup ↑<input id="import" type="file" accept="application/json,.json"></label></div></section><section class="panel"><h3>Activity history</h3>${activity()}</section>`}
function render(){for(const id of ['desktop-nav','mobile-nav'])$('#'+id).innerHTML=nav.map(([key,icon,label])=>`<button data-nav="${key}" class="${page===key?'active':''}" ${page===key?'aria-current="page"':''}><i aria-hidden="true">${icon}</i>${label}</button>`).join('');$('#page-label').textContent=nav.find(n=>n[0]===page)[2];$('#app').innerHTML=({home:dashboard,explore:discover,workspace,calendar,archive,profile}[page])();if(page==='explore'){updateGrid();$('#search').value=query;$('#chain').value=chain;$('#mode').value=mode;$('#sort').value=sort}}
function taskList(p){return p.tasks.map((t,i)=>`<button class="task ${state.done[p.id+':'+i]?'done':''}" data-task="${esc(p.id)}:${i}" aria-pressed="${!!state.done[p.id+':'+i]}"><span class="check">${state.done[p.id+':'+i]?'✓':''}</span><span>${esc(t)}</span></button>`).join('')}
function showDetail(id){const p=project(id);if(!p)return;openId=id;const r=rec(p);$('#detail-content').innerHTML=`<div class="detail-top"><button class="close" id="close" aria-label="Tutup detail">×</button><span class="project-symbol">${p.symbol}</span></div><div class="detail-body"><span class="eyeline">${p.custom?'PERSONAL RESEARCH':'DEMONSTRATION PROJECT'}</span><h2>${esc(p.name)}</h2><p>${esc(p.desc)}</p><div class="tags"><span class="tag-inline">${esc(p.category)}</span><span class="tag-inline">${esc(p.chain)}</span></div>${p.website?`<p><a class="secondary" href="${esc(p.website)}" target="_blank" rel="noopener noreferrer">Visit source ↗</a></p>`:''}<div class="notice">${p.custom?'Sumber ditambahkan sendiri dan belum diverifikasi oleh Airdrop Museum.':'Proyek fiktif untuk demonstrasi. Tidak ada kampanye atau reward nyata.'} Checklist adalah catatan pribadi, bukan bukti eligibility.</div><button class="secondary" data-save="${esc(id)}">${state.saved.includes(id)?'◆ Tracked · remove from workspace':'◇ Add to workspace'}</button><h3>Research checklist · ${done(p)}/${p.tasks.length}</h3>${taskList(p)}<form id="record-form" data-id="${esc(id)}"><h3>Project management</h3><div class="form-grid"><label>Status<select name="status">${Object.entries(labels).map(([k,v])=>`<option value="${k}" ${r.status===k?'selected':''}>${v}</option>`).join('')}</select></label><label>Priority<select name="priority">${['low','normal','high'].map(v=>`<option ${r.priority===v?'selected':''}>${v}</option>`).join('')}</select></label><label>Personal deadline<input type="date" name="due" value="${r.due}"></label><label>Cost · USD<input type="number" name="cost" min="0" max="1000000000" step="0.01" value="${r.cost}"></label><label>Actual reward · USD<input type="number" name="reward" min="0" max="1000000000" step="0.01" value="${r.reward}"></label></div><label>Research notes<textarea name="notes" maxlength="5000" rows="5" placeholder="Sources checked, risks, next steps…">${esc(r.notes)}</textarea></label><button class="primary">Save research</button><p class="connection">Completed, archived, dan reward dicatat manual oleh Anda.</p></form></div>`;if(!$('#detail').open)$('#detail').showModal()}
function addProject(){if(!$('#project-editor'))document.body.insertAdjacentHTML('beforeend','<dialog id="project-editor"></dialog>');$('#project-editor').innerHTML=`<div class="detail-body"><div class="section-title"><h2>Add a project</h2><button class="secondary" id="close-editor">×</button></div><p>Tambahkan proyek riset Anda. Sumber tidak dianggap terverifikasi otomatis.</p><form id="new-project"><label>Project name<input name="name" maxlength="80" required></label><label>Official source URL<input name="website" type="url" placeholder="https://…" required></label><div class="form-grid"><label>Category<select name="category">${['Testnet','DeFi','Gaming','AI','Infra','NFT'].map(c=>`<option>${c}</option>`).join('')}</select></label><label>Chain<input name="chain" maxlength="40" required></label></div><label>Description<textarea name="desc" maxlength="500" rows="2"></textarea></label><label>Research tasks · one per line<textarea name="tasks" maxlength="6000" rows="5" placeholder="Review official documentation\nCheck campaign rules" required></textarea></label><p class="connection">Maksimal 30 tugas. Jangan masukkan seed phrase, private key, atau token.</p><button class="primary">Create & track project</button></form></div>`;$('#project-editor').showModal()}
function download(content,name,type){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
document.addEventListener('click',e=>{const el=e.target.closest('button');if(!el)return;const d=el.dataset;if(d.nav)return navigate(d.nav);if(d.category){category=d.category;return updateGrid()}if(d.open)return showDetail(d.open);if(d.save){const p=project(d.save);if(!p)return;const saved=state.saved.includes(p.id);state.saved=saved?state.saved.filter(id=>id!==p.id):[...state.saved,p.id];if(!saved&&rec(p).status==='archived')rec(p).status='watching';persist(`${saved?'Untracked':'Tracked'} ${p.name}`);render();if($('#detail').open)showDetail(p.id);return}if(d.task){const id=openId,p=project(id);if(!p)return;state.done[d.task]=!state.done[d.task];if(!state.saved.includes(id))state.saved.push(id);persist(`Updated checklist: ${p.name}`);render();showDetail(id);return}if(d.month){month=new Date(month.getFullYear(),month.getMonth()+Number(d.month),1);render();return}if(el.id==='add-project')addProject();if(el.id==='close')$('#detail').close();if(el.id==='close-editor')$('#project-editor').close();if(el.id==='export')download(JSON.stringify({...state,exportedAt:new Date().toISOString()},null,2),'airdrop-museum-backup.json','application/json');if(el.id==='export-calendar'){const events=all().filter(p=>state.saved.includes(p.id)&&rec(p).due&&rec(p).status!=='archived').map(p=>icsEvent(p,rec(p)));if(!events.length)return toast('Belum ada deadline untuk diekspor.');download(['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//Airdrop Museum//Research Calendar//ID',...events,'END:VCALENDAR'].join('\r\n'),'airdrop-museum.ics','text/calendar')}});
document.addEventListener('input',e=>{if(e.target.id==='search'){query=e.target.value;updateGrid()}});
document.addEventListener('change',async e=>{if(['chain','mode','sort'].includes(e.target.id)){if(e.target.id==='chain')chain=e.target.value;if(e.target.id==='mode')mode=e.target.value;if(e.target.id==='sort')sort=e.target.value;updateGrid()}if(e.target.id==='import'){try{const file=e.target.files?.[0];if(!file)return;if(file.size>1000000)throw Error('Backup melebihi 1 MB.');state=mergeBackup(state,backup(await file.text(),demos),demos);persist('Imported backup');render();toast('Backup berhasil digabungkan.')}catch(err){toast(err.message)}}});
document.addEventListener('submit',e=>{if(!['new-project','record-form','profile-form'].includes(e.target.id))return;e.preventDefault();const data=Object.fromEntries(new FormData(e.target));try{if(e.target.id==='new-project'){if(state.custom.length>=100)throw Error('Maksimal 100 proyek pribadi.');const p=cleanProject({...data,id:'custom-'+(globalThis.crypto?.randomUUID?.()||Date.now().toString(36)+'-'+Math.random().toString(36).slice(2)),tasks:data.tasks.split('\n')});state.custom.push(p);state.saved.push(p.id);state=normalize(state,demos);persist(`Created ${p.name}`);$('#project-editor').close();navigate('workspace');showDetail(p.id)}else if(e.target.id==='record-form'){const id=e.target.dataset.id;state.records[id]=data;state=normalize(state,demos);if(!state.saved.includes(id))state.saved.push(id);persist(`Saved research: ${project(id).name}`);render();showDetail(id);toast('Research saved.')}else{state.name=data.name.trim()||'Museum Explorer';persist('Updated local profile');render();toast('Profile saved.')}}catch(err){let feedback=e.target.querySelector('.form-error');if(!feedback){feedback=document.createElement('p');feedback.className='notice form-error';feedback.setAttribute('role','alert');e.target.append(feedback)}feedback.textContent=err.message;toast(err.message)}});
$('#profile-top').onclick=()=>navigate('profile');$('#detail').addEventListener('click',e=>{if(e.target===e.currentTarget)e.currentTarget.close()});window.addEventListener('hashchange',()=>{const id=location.hash.slice(1);if(nav.some(n=>n[0]===id)&&id!==page){page=id;render()}});
page=nav.some(n=>n[0]===location.hash.slice(1))?location.hash.slice(1):'home';render();
const tg=window.Telegram?.WebApp;if(tg?.initData){try{tg.ready();tg.expand();if(tg.isVersionAtLeast('6.1')){tg.setHeaderColor('#f3f6fa');tg.setBackgroundColor('#f3f6fa')}tg.BackButton.onClick(()=>{if($('#detail').open)$('#detail').close();else navigate('home')});tg.BackButton.show()}catch{}}
